package com.faijan.interviewhub.config;
import com.faijan.interviewhub.entity.*;import com.faijan.interviewhub.repository.UserRepository;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration public class AdminBootstrap {
 private static final Logger log=LoggerFactory.getLogger(AdminBootstrap.class);
 @Bean CommandLineRunner createConfiguredAdmin(UserRepository users,PasswordEncoder encoder,@Value("${app.admin.email:}")String email,@Value("${app.admin.password:}")String password,@Value("${app.admin.full-name:Platform Admin}")String name){return args->{if(email.isBlank()||password.isBlank()){log.warn("No bootstrap admin created. Set ADMIN_EMAIL and ADMIN_PASSWORD to enable the first admin account.");return;}if(password.length()<12)throw new IllegalStateException("ADMIN_PASSWORD must be at least 12 characters");String normalizedEmail=email.trim().toLowerCase(java.util.Locale.ROOT);if(!users.existsByEmailIgnoreCase(normalizedEmail)){users.save(new AppUser(name.trim(),normalizedEmail,encoder.encode(password),UserRole.ADMIN));log.info("Bootstrap administrator created for {}",normalizedEmail);}else{AppUser existing=users.findByEmailIgnoreCase(normalizedEmail).orElseThrow();if(existing.getRole()!=UserRole.ADMIN)throw new IllegalStateException("ADMIN_EMAIL already belongs to a non-admin account. Configure an unused email for the bootstrap administrator.");}};}
}
